#!/usr/bin/env python3
"""Turn 35 Wave 52: THE OFFICIAL ECONOMY AND ACCOUNT ARTICLES - six more FTG support articles captured
in full, including two that are strategically decisive (the ONE-ACCOUNT rule and the 30-day reset
limit) - plus the Global Challenge Cup format, the 12th Man resolution and the Dynamic Star winner.

Wave 52 mines the official support portal's full article index (30 articles) and captures the six
hig-value articles not yet in the KB. Two of them change how the mission must be planned:

1. THE ONE-ACCOUNT RULE: 'To provide a fair, secure and more robust playing environment we have
   limited each player to one DLS account.' Combined with the fact that a profile is permanently
   bound to a Google (Android) or Apple (iOS) login, this means the account - and therefore the
   region seed that decides the matchmaker pool - is a ONE-WAY DOOR.

2. THE 30-DAY RESET LIMIT: Reset Profile (Settings > Advanced, skull icon) wipes everything
   including in-app purchases, and is limited to ONE RESET EVERY 30 DAYS. So a bad start is not
   freely re-rollable.

3. THE OFFICIAL COIN LIST names eleven sources and does NOT include DLL wins - confirming that
   coins come from Career surfaces while gems come from DLL.

4. THE OFFICIAL PLAYER-ACQUISITION ARTICLE independently confirms the per-match market refresh:
   'New players appear each in-game week i.e. after playing a single player match.' This is the
   second source on C-021's per-match side.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w52')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-462: official economy + accounts ----------
e_eco=new_ev("FTG support 214385285 (How do I earn coins in the app?), 213851369 (Is it possible to earn free coins?), 360004066417 (How do I obtain more players?), 360003914998 (What are Leaderboards?), 213851909 (How do I restart my career from the beginning?), 4413273241873 (How is save data stored and transferred in DLS?), 9804887423121 (Removal of Facebook Login from DLS), plus the full Dream League Soccer FAQ section index (30 articles)",
    "THE OFFICIAL ECONOMY AND ACCOUNT ARTICLES - six support articles captured in full, two of which are strategically decisive. (1) THE ONE-ACCOUNT RULE (4413273241873): 'To provide a fair, secure and more robust playing environment to our players we have limited each player to one DLS account.' Both the 'Manage Devices' and 'Link Profile' buttons live on the main menu under Options (gear icon, top left) > 'Advanced'. Transfer to another device you own is done by signing in with the same Google (Android only) or Apple (iOS only) account; cross-platform transfer (Android to iOS or vice versa) requires a code - click 'Manage Devices' on the old device, 'Generate Code', then type it into 'Link Profile' on the new device, and a code cannot be used on the device that generated it. The device list is manageable under 'Manage Devices' (remove with the X). CRITICAL WARNING: 'if you sign out of Sign in with Google / Sign in with Apple at any point whilst playing, your account will no longer be linked with your game profile and is susceptible to loss if you uninstall or change devices.' Codes and logins must not be shared - 'if it's lost via this method, it cannot be recovered.' (2) THE RESET-PROFILE RULE (213851909): a new career is started with the 'Reset Profile' button (skull and crossbones) under Settings (gear, top left) > Advanced. It is IRREVERSIBLE - 'it will not be possible to recover any previous game profiles that you had prior to using the button' - and it DESTROYS EVERYTHING: 'You will lose all your current progress including coins, gems and other consumables - this includes in-app purchases.' Decisively: 'Profile resets are limited to one reset every 30 days - so once your game profile has been reset, you will need to wait 30 days before you can start another new career.' (3) THE OFFICIAL COIN LIST (214385285): coins come from Winning Matches, Drawing Matches, Clean Sheets, Scoring Goals, Stadium Bonuses, Season Objectives, Season Pass rewards, Prize Ladder rewards, Final League Positions, Cup Wins, and Watching Video Clips (where available). NOTE WHAT IS ABSENT: DLL/multiplayer wins are NOT in the coin list - the coin economy is a Career-and-cups economy, which is the official mirror of the KB's finding that DLL pays GEMS while Career pays COINS. (4) FREE COINS (213851369): 'Yes, you can watch short video clips to earn free coins (subject to availability).' (5) THE OFFICIAL PLAYER-ACQUISITION ARTICLE (360004066417) names four routes - Transfers ('New players appear each in-game week i.e. after playing a single player match'), Scouts ('a selection of players to purchase at a discounted rate'), Agents ('will immediately add a player to your squad'), and the Prize Ladder ('awards special rare players when the criteria is met'). The Transfers wording is an INDEPENDENT OFFICIAL CONFIRMATION of the per-match market refresh. (6) LEADERBOARDS (360003914998): 'Leaderboards are a way to compare your performance against other players in Multiplayer (Dream League Live). Leaderboards reset at regular intervals (from 3-30 days) and users will receive prizes based on their position at the end time.' The official cadence is therefore a 3-30 day RANGE, which brackets the 10-day Progression Bank season.",
    "evidence/raw/turn35_w52/EV-462_official_economy_accounts.html",
    "OFFICIAL: (1) ONE DLS ACCOUNT PER PLAYER - 'we have limited each player to one DLS account'; profiles transfer via Google (Android) or Apple (iOS) sign-in, or cross-platform via a Generate Code from Manage Devices typed into Link Profile; signing out of Google/Apple unlinks the profile and risks total loss; lost profiles cannot be recovered. (2) RESET PROFILE (Settings > Advanced, skull icon) is irreversible, destroys all coins/gems/consumables INCLUDING in-app purchases, and is limited to ONE RESET EVERY 30 DAYS. (3) The official coin list has 11 sources and does NOT include DLL wins - coins are a Career/cups economy while DLL pays gems. (4) Free coins come from watching video clips. (5) Four official player routes: Transfers ('new players appear each in-game week i.e. after playing a single player match' - official per-match refresh), Scouts (discounted), Agents (immediate), Prize Ladder. (6) Leaderboards reset every 3-30 days with prizes by final position",
    quality="official")

add_claim("OFFICIAL: ONE DLS ACCOUNT PER PLAYER - 'to provide a fair, secure and more robust playing environment to our players we have limited each player to one DLS account.' A profile is permanently bound to a Sign in with Google (Android only) or Sign in with Apple (iOS only) login.", 1, "accounts/one-account-rule", [e_eco], notes="DECISIVE for mission planning - the account and its region seed are a one-way door")
add_claim("OFFICIAL: cross-platform profile transfer requires a code - click 'Manage Devices' on the old device, press 'Generate Code', then type it into 'Link Profile' on the new device. A generated code cannot be used on the device that generated it, and the linked-device list is managed (and devices removed) under 'Manage Devices'.", 1, "accounts/cross-platform-transfer", [e_eco])
add_claim("OFFICIAL WARNING: 'if you sign out of Sign in with Google / Sign in with Apple at any point whilst playing, your account will no longer be linked with your game profile and is susceptible to loss if you uninstall or change devices.' Shared codes and logins are unrecoverable if lost.", 1, "accounts/signout-unlink-risk", [e_eco], notes="Never sign out of the linked account on the mission profile")
add_claim("OFFICIAL: 'Reset Profile' (Settings > Advanced, skull-and-crossbones button) starts a new career but is IRREVERSIBLE - no previous profile can be recovered - and it destroys ALL progress including coins, gems, consumables AND in-app purchases.", 1, "accounts/reset-profile-cost", [e_eco])
add_claim("OFFICIAL: PROFILE RESETS ARE LIMITED TO ONE EVERY 30 DAYS - 'once your game profile has been reset, you will need to wait 30 days before you can start another new career.' A bad start is therefore NOT freely re-rollable.", 1, "accounts/reset-30-day-limit", [e_eco], notes="DECISIVE - commit to the account; there is no cheap re-roll")
add_claim("OFFICIAL COIN SOURCES (11): winning matches, drawing matches, clean sheets, scoring goals, stadium bonuses, season objectives, Season Pass rewards, Prize Ladder rewards, final league positions, cup wins, and watching video clips where available. NOTE: DLL/multiplayer wins are NOT in the list - the coin economy is a Career-and-cups economy.", 1, "economy/official-coin-sources", [e_eco], notes="Official mirror of the coins-from-Career / gems-from-DLL split")
add_claim("OFFICIAL: free coins are earned by watching short video clips, 'subject to availability'.", 1, "economy/free-coins-ads", [e_eco])
add_claim("OFFICIAL PLAYER-ACQUISITION ROUTES (4): Transfers ('new players appear each in-game week i.e. after playing a single player match'), Scouts ('a selection of players to purchase at a discounted rate'), Agents ('will immediately add a player to your squad') and the Prize Ladder ('awards special rare players when the criteria is met').", 1, "transfers/official-acquisition-routes", [e_eco])
add_claim("OFFICIAL CONFIRMATION OF THE PER-MATCH MARKET REFRESH: 'New players appear each in-game week i.e. after playing a single player match.' This is an independent official source on the per-match side of C-021, alongside the community reports.", 1, "transfers/per-match-refresh-official", [e_eco], notes="Advances C-021 - the per-match side now has official backing")
add_claim("OFFICIAL LEADERBOARDS: leaderboards compare your performance against other players in Dream League Live, 'reset at regular intervals (from 3-30 days)', and pay prizes based on your position at the end time. The official cadence is a 3-30 day range.", 1, "dll/official-leaderboard-cadence", [e_eco], notes="Resolves the cadence conflict as a range, bracketing the 10-day Progression Bank season")

# ---------- EV-463: cups, 12th Man, Dynamic Stars ----------
e_cup=new_ev("dls-wiki.fandom.com/wiki/Leagues (Global Challenge Cup format), dream-league-soccer.fandom.com/wiki/Global_Challenge_Cup, r/DreamLeagueSoccer 1ib3c2g (GCC format discussion, 128 teams, '3 teams twice just as last year ucl format'), n623r2 (2021, group stage then R16 and QF in extra time), Apple App Store DLS26 version history (13.120, 25 Mar 2026: '12th Man - The DLS community has voted, and we've added this extra superstar to the collection'), r/DLS 1rf90a7 (26 Feb 2026 mid-season megathread), 1r0xvwd (10 Feb 2026 Dream Stars 2026 candidates), 1vbqucs (31 Jul 2026 TOTY/Dream Star colour permanence), YouTube 'DLS 26 WORLD DYNAMIC STAR WINNER NICO WILLIAMS' (21 Jul 2026), sportsdunia Dynamic Stars event guide (collect until 20 Jul 2026), dreamkitsapp.com/data (card-type ratings)",
    "THE GLOBAL CHALLENGE CUP FORMAT, THE 12TH MAN RESOLUTION, AND THE DYNAMIC STAR WINNER. GCC FORMAT (C-013 substantially resolved): 'Global Challenge Cup can be attended in every divisions, you will be competed with 4 teams in your group, 2 teams with the most points will be qualified. If you concede in the fixtures after being qualified, you will be eliminated.' The fandom wiki describes it as working 'like the FA Cup and The Carabao cup where its target is to not lose any matches at it or your team gets eliminated', running 'from the Academy Division to Legendary Divisions'. A community thread adds the scale - 'the GCC right now is made of 128 teams' - and the fixture shape: 'basically, you play 3 teams twice just as last year ucl format', i.e. four teams per group, home and away (six group matches), top two through, then a knockout of round of 32, round of 16, quarter-finals, semi-finals and final (a 2021 thread describes surviving the group stage, a 3-goal win in the round of 16 and a one-goal win in extra time in the quarter-final). So the format is a 128-team, 4-team-group, top-2-qualify, then straight knockout with extra time - available in every division from Academy up. THE 12TH MAN: the App Store version history for v13.120 (25 Mar 2026) reads '12th Man - The DLS community has voted, and we've added this extra superstar to the collection', so the vote CONCLUDED and the winner WAS ADDED in the 25 March build. FTG still does not name the player in any official channel, and the community's guesses (Kane among them) remain guesses. The mechanic is therefore CLOSED (voted and shipped in 13.120) while the identity stays unnamed. THE DYNAMIC STAR WINNER: a YouTube video dated 21 Jul 2026 is titled 'DLS 26 WORLD DYNAMIC STAR WINNER NICO WILLIAMS | DLS WORLD CUP DYNAMIC CHAMPIONS', and the Dynamic Stars event ran until 20 July 2026 - so Nico Williams is the reported World Dynamic Star winner of the summer 2026 event. DREAM STARS 2026 CANDIDATES: a community pattern list of the boosted players and their BASE card ratings - Wood 77, Paz 79, Huijsen 79, Stejn 74, Vivian 79 (80 after update), McTominay 80 (82 after update), Trafford 75, Cherki 78, Baena 80, Robinson 79, Santos 75 - with the observation that 'Dream Stars base cards are blue/rare' while the boosted Dream Star card is purple. CARD COLOUR PERMANENCE: 'TOTY cards will be forever green, Dream stars will forever be purple, Champions will forever be blue.' MID-SEASON RATING CHANGES (26 Feb 2026 megathread): 'Alvarez retains, Lookman retains, Baena -1' and 'Raya 83 > 84, Gabriel 84 > 85, Merino 79 > 80, Zubimendi 81 > 82, Trossard 79 > 80'. CARD-TYPE RATINGS (dreamkitsapp): World Winners Cucurella 85 LB, World Heroes Messi 87 SS, Team of 2025 Donnarumma 86 GK, Champion players Modric 86 CM, Star players Sarr 83 CB, Kick-off Stars Raphinha 85 LW.",
    "evidence/raw/turn35_w52/EV-463_cups_and_dream_stars.html",
    "GCC FORMAT (C-013 substantially resolved): 128 teams, FOUR per group, home and away (3 opponents twice, six group matches), TOP TWO qualify, then straight knockout (R32, R16, QF, SF, final) with extra time; available in every division from Academy to Legendary, and a loss after qualifying eliminates you. THE 12TH MAN: the App Store history for v13.120 (25 Mar 2026) confirms the community vote concluded and the extra superstar WAS ADDED to the collection - the mechanic is CLOSED, but FTG never names the player, so the identity stays unknown. DYNAMIC STAR WINNER: Nico Williams is the reported World Dynamic Star winner of the summer 2026 event (video dated 21 Jul 2026, event ran to 20 Jul). DREAM STARS 2026: candidate base ratings published (Wood 77, Paz 79, Huijsen 79, Stejn 74, Vivian 79-80, McTominay 80-82, Trafford 75, Cherki 78, Baena 80, Robinson 79, Santos 75); Dream Star base cards are blue/rare, boosted Dream Stars are purple. CARD COLOURS ARE PERMANENT: TOTY green, Dream Stars purple, Champions blue. Mid-season Feb 2026 changes: Raya 83>84, Gabriel 84>85, Merino 79>80, Zubimendi 81>82, Trossard 79>80, Baena -1",
    quality="community")

add_claim("THE GLOBAL CHALLENGE CUP FORMAT: 128 teams, four per group played home and away (three opponents twice, six group matches), the top two qualify, then a straight knockout of round of 32, round of 16, quarter-finals, semi-finals and final with extra time. A loss after qualifying eliminates you.", 2, "cups/gcc-format", [e_cup], notes="C-013 substantially resolved")
add_claim("The Global Challenge Cup is available in EVERY division, from the Academy Division up to the Legendary Division, and works 'like the FA Cup and The Carabao cup where its target is to not lose any matches at it or your team gets eliminated'.", 2, "cups/gcc-every-division", [e_cup])
add_claim("THE 12TH MAN MECHANIC IS CLOSED: the App Store version history for v13.120 (25 Mar 2026) states '12th Man - The DLS community has voted, and we've added this extra superstar to the collection', so the vote concluded and the winner was shipped in the 25 March build. FTG never names the player, so the identity remains unknown - treat the community guesses (Kane among them) as guesses.", 2, "cards/12th-man-mechanic-closed", [e_cup], notes="Advances the 12th Man gap: mechanism dated and closed, identity still unnamed")
add_claim("NICO WILLIAMS is the reported WORLD DYNAMIC STAR winner of the summer 2026 Dynamic Stars event (a video dated 21 Jul 2026 titles him the winner; the event ran until 20 Jul 2026).", 3, "cards/dynamic-star-winner-nico-williams", [e_cup], notes="Single YouTube source - treat as reported, not official")
add_claim("Dream Stars 2026 candidate BASE ratings (community pattern list): Wood 77, Paz 79, Huijsen 79, Stejn 74, Vivian 79 (80 after update), McTominay 80 (82 after update), Trafford 75, Cherki 78, Baena 80, Robinson 79, Santos 75. Dream Star base cards are blue/rare, and the boosted Dream Star card is purple.", 3, "cards/dream-stars-2026-candidates", [e_cup])
add_claim("CARD COLOURS ARE PERMANENT by type: TOTY cards are forever green, Dream Stars forever purple, Champions forever blue.", 3, "cards/colour-permanence", [e_cup])
add_claim("Mid-season rating changes (26 Feb 2026 megathread): Raya 83 to 84, Gabriel 84 to 85, Merino 79 to 80, Zubimendi 81 to 82, Trossard 79 to 80, Baena -1, with Alvarez and Lookman retaining.", 3, "patching/mid-season-feb-2026-changes", [e_cup])
add_claim("Card-type sample ratings (dreamkitsapp): World Winners Cucurella 85 LB, World Heroes Messi 87 SS, Team of 2025 Donnarumma 86 GK, Champion players Modric 86 CM, Star players Sarr 83 CB, Kick-off Stars Raphinha 85 LW.", 3, "cards/card-type-sample-ratings", [e_cup])

for name in ('EV-462_official_economy_accounts.html','EV-463_cups_and_dream_stars.html'):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
